 let left=42,height=Math.max(420,innerHeight-360);try{const x=JSON.parse(localStorage.getItem('bytequest.workspace')||'{}');left=Math.min(70,Math.max(25,x.left||left));height=Math.min(1200,Math.max(280,x.height||height));}catch{}
 const save=()=>{try{localStorage.setItem('bytequest.workspace',JSON.stringify({left,height}));}catch{}};
